mapper.select:
SELECT reservation_id, reservation_no, patient_id, patient_name, department_id, department_name, doctor_id, doctor_name, reserved_at, status, note, is_active, inactive_at, inactive_reason_code, inactive_reason_text, canceled_at, cancel_reason_code, cancel_reason_text, created_by, updated_by, created_at, updated_at FROM reservation
AND reservation_no = #{searchValue}
AND patient_id = #{searchValue}
AND status = #{searchValue}
ORDER BY reservation_id
